INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (95, 'S_INST200', 'Country instrumental. Fiddle plays a bright, twangy melody with double stops and quick ornamental slides. Dobro provides resonant, sliding fills with a metallic, nasal tone and fingerpicked arpeggios. Acoustic guitar strums steady, open-chord patterns with a warm, clean attack. The drums feature a simple kick-snare shuffle with a light tambourine accent. The arrangement is easygoing and pastoral, with trading solos between fiddle and dobro. 115 BPM in A Major, 4/4 time signature.', NULL, 'Country', 115, 'A Major', '4/4', 'Session 2, Verse-Chorus, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (96, 'S_INST200', 'Raga instrumental. Sitar plays intricate, microtonal melodic passages with sustained bends and rapid taan runs across the upper frets. Tabla provides complex rhythmic cycles with sharp, crisp bols and deep resonant bass strokes. Tanpura sustains a shimmering, hypnotic drone with rich overtones that anchor the tonal center. The arrangement is meditative and exploratory, gradually building intensity through rhythmic interplay and ascending melodic phrases. 70 BPM in A Mixolydian, 7/8 time signature.', NULL, 'Raga', 70, 'A Mixolydian', '7/8', 'Session 2, Through-composed, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (97, 'S_INST200', 'Death Metal instrumental. Heavily distorted guitar plays brutal, tremolo-picked riffs with chromatic descents and dissonant pinch harmonics. Blast beats deliver relentless, machine-gun snare hits at extreme speed with thundering double-kick patterns underneath. Guttural bass provides a thick, grinding low-end with rapid-fire picking that shadows the guitar riffs. The arrangement is chaotic and unrelenting, with sudden tempo shifts and breakdowns. 205 BPM in A Minor, 4/4 time signature.', NULL, 'Death Metal', 205, 'A Minor', '4/4', 'Session 2, Through-composed, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (98, 'S_INST200', 'Modal Jazz instrumental. Muted trumpet plays cool, restrained phrases with a breathy, intimate tone and sparse, lyrical phrasing over the Dorian mode. Piano provides shimmering, quartal voicings with suspended chords and gentle comping that avoids traditional progressions. Upright bass walks in a relaxed, unhurried manner with a deep, woody tone and occasional melodic departures. The drums feature a light ride cymbal shimmer with soft brush patterns. The arrangement is spacious and contemplative, leaving generous room for silence. 68 BPM in D Dorian, 4/4 time signature.', NULL, 'Modal Jazz', 68, 'D Dorian', '4/4', 'Session 2, AABA, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (99, 'S_INST200', 'Spanish Fusion instrumental. Nylon-string guitar plays rapid rasgueado strumming patterns with fiery picado runs and percussive golpe taps on the body. Cajón provides earthy, resonant bass tones and crisp, slapped high accents with flamenco-style rhythmic patterns. Upright bass delivers warm, melodic walking lines with occasional pizzicato fills. The arrangement is passionate and dynamic, alternating between explosive rhythmic bursts and tender, rubato melodic passages. 95 BPM in E Phrygian, 12/8 time signature.', NULL, 'Spanish Fusion', 95, 'E Phrygian', '12/8', 'Session 2, Through-composed, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (100, 'S_INST200', 'Medieval instrumental. Recorder plays a lilting, modal melody with ornamental trills and clean, pure intonation. Lute provides delicate, fingerpicked accompaniment with open-string drones and Renaissance-era voicings. Hurdy-gurdy adds a buzzing, sustained drone beneath rhythmic melodic phrases with its distinctive mechanical vibrato. The arrangement is courtly and archaic, evoking ancient dance halls with layered counterpoint between recorder and lute. 80 BPM in D Mixolydian, 3/4 time signature.', NULL, 'Medieval', 80, 'D Mixolydian', '3/4', 'Session 2, Binary (AB), 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (101, 'S_INST200', 'Hindustani Classical instrumental. Bansuri plays slow, breathy melodic phrases with delicate meend glides and gentle gamak ornaments that explore the ascending raga structure. Tabla provides a hypnotic, cyclical rhythmic pattern with soft fingertip strokes on the dayan and deep bass resonance from the bayan. Tanpura sustains a warm, continuous drone with overlapping harmonics that fill the sonic space. The arrangement is meditative and unhurried, unfolding gradually through alap-like phrases. 55 BPM in C Lydian, 7/8 time signature.', NULL, 'Hindustani Classical', 55, 'C Lydian', '7/8', 'Session 2, Through-composed, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (102, 'S_INST200', 'Greek Rebetiko instrumental. Bouzouki plays rapid tremolo picking with bright, metallic tone and modal melodic runs in the Phrygian mode. Guitar provides rhythmic strumming with accented offbeats and warm, nylon-string tone. Violin adds expressive, ornamented counter-melodies with wide vibrato and passionate slides between notes. The drums feature a light darbuka-like pattern with sharp rim clicks. The arrangement is smoky and heartfelt, building from a solo bouzouki introduction into a full ensemble dance. 90 BPM in D Phrygian, 9/8 time signature.', NULL, 'Greek Rebetiko', 90, 'D Phrygian', '9/8', 'Session 2, Strophic, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (103, 'S_INST200', 'Blues instrumental. Slide guitar plays raw, bottleneck phrases with gritty tone and expressive quarter-tone bends that cry across the twelve-bar form. Harmonica provides wailing, bent notes with a cupped, overdriven tone and rhythmic chugging train patterns. Stomp box delivers a steady, foot-stomped pulse with a dry, percussive thump on every beat. The arrangement is stripped-down and earthy, with call-and-response between slide guitar and harmonica over a hypnotic groove. 65 BPM in A Mixolydian, 12/8 time signature.', NULL, 'Blues', 65, 'A Mixolydian', '12/8', 'Session 2, 12-bar blues, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (104, 'S_INST200', 'Psychedelic Rock instrumental. Mellotron plays haunting, choir-like pads with a lo-fi, tape-warbled texture and slow, sweeping filter movement. Fuzz guitar delivers thick, saturated riffs with heavy sustain and feedback-laden lead lines. Wah-wah bass provides a funky, squelching low-end with rhythmic filter sweeps and rubbery attack. The drums feature a loose, swinging groove with splashy cymbals and tom-heavy fills. The arrangement is sprawling and hypnotic, layering swirling textures into a kaleidoscopic sonic landscape. 105 BPM in E Dorian, 4/4 time signature.', NULL, 'Psychedelic Rock', 105, 'E Dorian', '4/4', 'Session 2, Through-composed, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (105, 'S_INST200', 'Whole Tone Experiment instrumental. Piano plays floating, ambiguous chords built entirely from whole-tone intervals with a crystalline, bell-like touch. Vibraphone provides shimmering, sustained tones with motorized tremolo creating a dreamy, wavering quality. Flute adds airy, pure melodic lines that glide through the symmetrical scale with breathy articulation. The arrangement is ethereal and disorienting, with no resolution or tonal center, suspended in a weightless harmonic space. 72 BPM in C Whole Tone, 5/4 time signature.', NULL, 'Whole Tone Experiment', 72, 'C Whole Tone', '5/4', 'Session 2, Free-form, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (106, 'S_INST200', 'Locrian Drone instrumental. Synthesizer drone provides an unsettling, continuously evolving tonal mass with the diminished fifth creating inherent tension. Bass guitar plays slow, deliberate notes with a dark, muffled tone and heavy string rattle. Sparse drums deliver occasional, isolated hits on the floor tom and ride bell with long silences between strikes. The arrangement is bleak and unstable, built on the Locrian mode''s natural dissonance with no resolution. 42 BPM in B Locrian, 4/4 time signature.', NULL, 'Locrian Drone', 42, 'B Locrian', '4/4', 'Session 2, Free-form, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (107, 'S_INST200', 'Symphonic Metal instrumental. Orchestral strings play sweeping, cinematic phrases with lush legato lines and dramatic crescendos. Distorted guitar delivers aggressive, palm-muted riffs with tight, chugging rhythms and soaring lead melodies. Double-kick drums provide thundering, rapid-fire bass drum patterns with blast-beat intensity and precise snare accents. The arrangement is grandiose and epic, blending orchestral grandeur with crushing metal power in alternating passages. 158 BPM in Eb Minor, 4/4 time signature.', NULL, 'Symphonic Metal', 158, 'Eb Minor', '4/4', 'Session 2, Verse-Chorus-Bridge, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (108, 'S_INST200', 'Chamber Music instrumental. String quartet plays refined, interlocking melodic lines with precise intonation and delicate dynamic shading. Clarinet provides a warm, rounded tone with expressive legato phrasing and gentle vibrato on sustained notes. Piano adds sparse, supportive chords with a crystalline touch and occasional melodic dialogues with the strings. The arrangement is elegant and conversational, with each instrument taking turns leading the thematic material through a rondo structure. 100 BPM in Eb Minor, 3/4 time signature.', NULL, 'Chamber Music', 100, 'Eb Minor', '3/4', 'Session 2, Rondo (ABACA), 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (109, 'S_INST200', 'Funk instrumental. Clavinet plays percussive, staccato chord stabs with a bright, biting tone and aggressive muted scratch patterns. Slap bass delivers popping, syncopated lines with thumb-slapped low notes and snapped high accents creating a tight, bouncing groove. Wah-wah guitar provides rhythmic, filtered chord chops with a squelching, expressive tone on the offbeats. The drums feature a tight, syncopated groove with ghost notes on the snare and a deep, punchy kick. The arrangement is relentlessly groovy with a locked-in pocket. 108 BPM in F Minor, 4/4 time signature.', NULL, 'Funk', 108, 'F Minor', '4/4', 'Session 2, Verse-Chorus, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (110, 'S_INST200', 'Baroque instrumental. Harpsichord plays ornate, terraced-dynamic passages with rapid trills and mordents in a contrapuntal texture. Violin provides singing, sustained melodic lines with precise Baroque bowing and restrained vibrato. Cello adds a warm, resonant bass line with steady eighth-note movement that outlines the harmonic structure. The arrangement is polished and formal, with strict binary form and elegant ornamentation throughout. 80 BPM in F Major, 3/4 time signature.', NULL, 'Baroque', 80, 'F Major', '3/4', 'Session 2, Binary (AB), 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (111, 'S_INST200', 'Progressive House instrumental. Supersaw synth plays wide, euphoric chord stacks with slow filter automation and stereo-widened detuning. Sidechained sub-bass provides deep, pulsing low-end that rhythmically ducks beneath the kick drum with a smooth, rounded envelope. Filtered sweep creates rising tension with white noise and resonant filter sweeps building toward the drop. The drums feature a four-on-the-floor kick with crisp hi-hat patterns and layered clap accents. The arrangement builds methodically through a long, tension-releasing structure. 128 BPM in F Minor, 4/4 time signature.', NULL, 'Progressive House', 128, 'F Minor', '4/4', 'Session 2, Build-Drop, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (112, 'S_INST200', 'Solo Piano Nocturne instrumental. Grand piano plays tender, singing melodic lines in the right hand with gentle rubato and expressive dynamic nuance. The left hand provides a flowing, arpeggiated accompaniment with wide-voiced chords that create a sense of expansive harmonic depth. Sustained pedal allows notes to blend into shimmering overtone washes. The arrangement is intimate and solitary, with pauses and silences as expressive as the notes themselves. 52 BPM in F Minor, 6/8 time signature.', NULL, 'Solo Piano Nocturne', 52, 'F Minor', '6/8', 'Session 2, Through-composed, 1 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (113, 'S_INST200', 'Dave Brubeck-style Jazz instrumental. Piano plays bright, percussive block chords with angular, rhythmically adventurous phrasing that navigates the asymmetric meter. Alto saxophone provides a cool, fluid melodic line with a clear, focused tone and effortless runs across the odd time signature. Upright bass walks with a strong, woody pulse that anchors the shifting metric groupings. The drums feature a light, swinging ride pattern adapted to the five-beat cycle with nimble snare accents. The arrangement is intellectual and playful, exploring rhythmic displacement. 170 BPM in Eb Major, 5/4 time signature.', NULL, 'Dave Brubeck-style Jazz', 170, 'Eb Major', '5/4', 'Session 2, AABA, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (114, 'S_INST200', 'Bulgarian Folk instrumental. Kaval plays a piercing, breathy melody with rapid ornamental grace notes and wide intervallic leaps characteristic of Thracian folk. Gadulka provides a buzzing, bowed drone with sympathetic string resonance and rhythmic melodic figures. Tapan delivers a powerful, asymmetric dance rhythm with deep bass booms and sharp rim strikes that emphasize the irregular groupings. The arrangement is festive and driving, built on the additive meter''s infectious energy. 130 BPM in A Minor, 11/8 time signature.', NULL, 'Bulgarian Folk', 130, 'A Minor', '11/8', 'Session 2, Strophic, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (115, 'S_INST200', 'Gamelan instrumental. Metalophone plays interlocking, cyclical melodic patterns with a bright, resonant ring and precise rhythmic placement within the kotekan texture. Gong provides deep, resonant punctuations that mark the colotomic structure with long, shimmering decay. Bamboo flute adds a breathy, floating melody with gentle pitch bends above the metallic layers. The arrangement is cyclical and meditative, with layered interlocking parts that create a dense, shimmering polyrhythmic web. 55 BPM in C Pentatonic, 7/8 time signature.', NULL, 'Gamelan', 55, 'C Pentatonic', '7/8', 'Session 2, Cyclical, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (116, 'S_INST200', 'Afro-Cuban 6/8 instrumental. Congas play a driving tumbao pattern with open tones, slaps, and muted strokes creating a polyrhythmic conversation between drums. Tres guitar provides bright, syncopated arpeggiated patterns with a metallic, trebly tone and rapid fingerpicking. Bass delivers a deep, steady pulse with occasional melodic anticipations that lock into the clave rhythm. The arrangement is fiery and dance-driven, building through layered percussion and call-and-response between tres and congas. 100 BPM in F Minor, 6/8 time signature.', NULL, 'Afro-Cuban 6/8', 100, 'F Minor', '6/8', 'Session 2, Verse-Montuno, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (117, 'S_INST200', 'Slow Blues instrumental. Overdriven guitar plays aching, sustained bends with thick, creamy tone and stinging vibrato on each note. Hammond organ provides warm, swirling chords with Leslie speaker rotation creating a pulsing, three-dimensional texture. The drums feature a deep, loping shuffle with heavy hi-hat swings and a lazy, behind-the-beat snare. The arrangement is soulful and raw, with long, expressive guitar phrases breathing over the organ''s slow harmonic movement. 58 BPM in Bb Minor, 12/8 time signature.', NULL, 'Slow Blues', 58, 'Bb Minor', '12/8', 'Session 2, 12-bar blues, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (118, 'S_INST200', 'West African Percussion instrumental. Djembe plays a complex, layered pattern with sharp slaps, deep bass tones, and rapid open-hand rolls that anchor the polyrhythmic structure. Balafon provides bright, wooden melodic phrases with a resonant, buzzing sustain from gourd resonators underneath. Shekere adds a shimmering, rattling texture with rhythmic shakes and catches that weave between the djembe accents. The arrangement is communal and ecstatic, building from a single drum pattern into a full, interlocking percussion ensemble. 100 BPM in A Minor, 12/8 time signature.', NULL, 'West African Percussion', 100, 'A Minor', '12/8', 'Session 2, Call-and-Response, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (119, 'S_INST200', 'Gospel Slow instrumental. Organ plays rich, sustained chords with a warm, tremolo-heavy tone and slow, devotional harmonic movement. Piano provides gentle, rolling arpeggiated figures with a soft, rounded touch and occasional bluesy grace notes. Bass guitar delivers deep, melodic lines with a smooth, pillowy tone that emphasizes the root movement with soulful passing tones. The arrangement is reverent and unhurried, with the organ swelling gradually through each phrase. 50 BPM in Ab Major, 12/8 time signature.', NULL, 'Gospel Slow', 50, 'Ab Major', '12/8', 'Session 2, Strophic, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (120, 'S_INST200', 'Samba instrumental. Surdo provides a deep, booming bass pulse with alternating open and muted strokes that define the two-beat samba groove. Pandeiro plays rapid, intricate patterns with thumb rolls, fingertip slaps, and shaken accents creating a dense, shimmering rhythmic layer. Cavaquinho strums bright, percussive chords with a trebly, cutting tone and tight rhythmic syncopation. The arrangement is jubilant and propulsive, with layered percussion building an irresistible dance energy. 105 BPM in A Major, 2/4 time signature.', NULL, 'Samba', 105, 'A Major', '2/4', 'Session 2, Strophic, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (121, 'S_INST200', 'Quickstep instrumental. Brass section plays bright, staccato phrases with crisp articulation and rapid melodic runs that drive the breakneck tempo. Piano provides sparkling, rhythmic comping with light, bouncing touch and quick harmonic changes. Upright bass walks at an exhilarating pace with a clear, punchy tone and relentless four-to-the-bar pulse. The drums feature a tight, snapping hi-hat pattern with sharp snare accents. The arrangement is breathlessly energetic and elegant, designed for fast ballroom dancing. 200 BPM in Bb Major, 2/4 time signature.', NULL, 'Quickstep', 200, 'Bb Major', '2/4', 'Session 2, AABA, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (122, 'S_INST200', 'Mazurka instrumental. Piano plays spirited, accented phrases with emphasis on the second and third beats and bright, sparkling runs between thematic statements. Violin provides a singing, lyrical melody with warm vibrato and characteristic dotted-rhythm figures. Cello adds a rich, sustained bass line with strong bowing and occasional passionate melodic ascents. The arrangement is dance-like and romantic, with rubato passages alternating with strict rhythmic sections. 145 BPM in F# Minor, 3/4 time signature.', NULL, 'Mazurka', 145, 'F# Minor', '3/4', 'Session 2, AABB, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (123, 'S_INST200', 'Minuet instrumental. Harpsichord plays a graceful, ornate melody with trills and turns in a refined, terraced-dynamic style. Flute provides a clear, singing counter-melody with pure intonation and delicate mordents that interweave with the harpsichord. Violin adds elegant, sustained phrases with restrained vibrato and precise, Baroque-style bowing. The arrangement is courtly and measured, with balanced phrases and a stately, dignified character. 112 BPM in Db Major, 3/4 time signature.', NULL, 'Minuet', 112, 'Db Major', '3/4', 'Session 2, Binary (AB), 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (124, 'S_INST200', 'Glacial Ambient instrumental. Frozen pad provides an immense, slowly shifting tonal mass with icy, crystalline overtones and glacial filter movement. Ice texture creates brittle, crackling granular sounds with high-frequency sparkle and irregular, nature-derived patterns. Distant bell produces isolated, pure tones with long, fading decay that ring out across the vast sonic emptiness. The arrangement is nearly motionless, with events separated by long stretches of quiet and imperceptible evolution. 20 BPM in C# Minor, 4/4 time signature.', NULL, 'Glacial Ambient', 20, 'C# Minor', '4/4', 'Session 2, Free-form, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (125, 'S_INST200', 'Sufi Drone instrumental. Ney plays a haunting, breathy melody with microtonal inflections and long, sustained notes that quiver with devotional intensity. Frame drum provides a slow, hypnotic pulse with deep, resonant strokes and gentle finger-roll embellishments. Sustained chant creates a warm, humming drone with overtone-rich harmonics that merge with the ney''s breathy tone. The arrangement is mystical and trance-inducing, spiraling slowly through repeated modal phrases. 38 BPM in Eb Minor, 4/4 time signature.', NULL, 'Sufi Drone', 38, 'Eb Minor', '4/4', 'Session 2, Through-composed, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (126, 'S_INST200', 'Drum and Bass instrumental. Reese bass provides a thick, detuned, growling low-end with slow-moving pitch modulation and heavy sub-frequency weight. Breakbeat drums deliver rapid, syncopated patterns with chopped-up Amen breaks, sharp snare rolls, and punchy, layered kicks. Atmospheric pad creates a wide, reverb-soaked texture with ethereal chord washes hovering above the frenetic rhythm section. The arrangement is high-energy and relentless, with tension-building breakdowns and explosive drops. 176 BPM in Ab Minor, 4/4 time signature.', NULL, 'Drum and Bass', 176, 'Ab Minor', '4/4', 'Session 2, Build-Drop, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (127, 'S_INST200', 'Grindcore instrumental. Blast beats deliver savage, hyper-speed snare and kick patterns with raw, clipping intensity and zero swing. Distorted guitar plays frantic, dissonant riffs with extreme palm-muting and atonal tremolo-picked passages at breakneck speed. Screaming bass provides a gnarly, distorted low-end with aggressive picking that blurs into a wall of noise. The arrangement is short, violent, and chaotic, with abrupt tempo changes and microsecond-length sections. 240 BPM in C# Minor, 4/4 time signature.', NULL, 'Grindcore', 240, 'C# Minor', '4/4', 'Session 2, Through-composed, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (128, 'S_INST200', 'Cumbia instrumental. Accordion plays bright, cheerful melodic runs with a bouncy, syncopated attack and quick bellows articulation. Güiro provides a scratchy, rhythmic scraping pattern with steady, repetitive strokes that drive the cumbia shuffle. Cowbell adds a sharp, metallic rhythmic accent with a consistent, dance-floor-ready pulse. The drums feature a distinctive cumbia pattern with a shuffling kick and snare groove. The arrangement is festive and infectious, with a rolling, circular groove. 92 BPM in Bb Major, 4/4 time signature.', NULL, 'Cumbia', 92, 'Bb Major', '4/4', 'Session 2, Strophic, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (129, 'S_INST200', 'Acid House instrumental. 303 bassline plays squelchy, resonant arpeggiated patterns with screaming filter sweeps and distinctive acid squelch. TR-909 drums provide a punchy, four-on-the-floor kick with crisp, snapping claps and sizzling open hi-hats. Filter sweeps create long, evolving tonal transformations with rising and falling resonant peaks across the frequency spectrum. The arrangement is hypnotic and repetitive, with the 303 gradually morphing through increasingly wild filter modulations over the relentless beat. 126 BPM in Db Minor, 4/4 time signature.', NULL, 'Acid House', 126, 'Db Minor', '4/4', 'Session 2, Loop-based, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (130, 'S_INST200', 'Neoclassical instrumental. Piano plays a tender, singing melody with a warm, rounded touch and expressive rubato phrasing. Cello provides a rich, sustained bass line with deep bowing and occasional passionate melodic solos that ascend into the upper register. Violin adds a soaring, lyrical counter-melody with warm vibrato and delicate dynamic shading. The arrangement is elegant and emotionally restrained, with each instrument conversing in an intimate chamber setting. 75 BPM in C# Minor, 3/4 time signature.', NULL, 'Neoclassical', 75, 'C# Minor', '3/4', 'Session 2, Ternary (ABA), 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (131, 'S_INST200', 'Electro Swing instrumental. Brass section plays punchy, vintage-style stabs with bright, muted trumpet accents and tight trombone riffs. Electronic beats provide crisp, modern kick-and-clap patterns with glitchy, chopped-up swing samples and sidechain-pumping dynamics. Double bass delivers a walking, plucked bass line with a warm, woody tone and swing-era phrasing. The arrangement is a high-energy collision of 1920s jazz and modern electronic production, with filtered drops and brass breakdowns. 128 BPM in A Major, 4/4 time signature.', NULL, 'Electro Swing', 128, 'A Major', '4/4', 'Session 2, Verse-Chorus, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (132, 'S_INST200', 'Dub instrumental. Heavy bass provides a deep, sub-heavy foundation with slow, melodic bass lines and a round, analog warmth. Spring reverb drums deliver a spacious, echo-drenched rhythm with the snare swimming in long, cascading reverb trails. Echo guitar plays sparse, clean chords with heavy delay creating rhythmic, repeating patterns that drift across the stereo field. The arrangement is cavernous and hypnotic, with dramatic dub drops where instruments suddenly vanish into reverb space. 75 BPM in Eb Minor, 4/4 time signature.', NULL, 'Dub', 75, 'Eb Minor', '4/4', 'Session 2, Verse-Chorus, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (133, 'S_INST200', 'Tango instrumental. Bandoneón plays passionate, sustained chords with dramatic bellows accents and rapid, staccato melodic runs. Violin provides an intense, soaring melody with heavy vibrato, sharp accents, and expressive slides between notes. Piano delivers rhythmic, marcato chord stabs with percussive attack and syncopated accompaniment patterns. The arrangement is dramatic and sultry, with sudden dynamic contrasts between whispered phrases and explosive, full-ensemble passages. 66 BPM in Ab Minor, 4/4 time signature.', NULL, 'Tango', 66, 'Ab Minor', '4/4', 'Session 2, AABB, 3 instruments');
INSERT INTO songs_test_lab (test_id, series, sp, lyrics, genre, bpm, key_sig, time_sig, notes) VALUES (134, 'S_INST200', 'Power Metal instrumental. Fast arpeggiated guitar plays blazing, sweep-picked runs with a bright, saturated distortion and soaring, neoclassical melodic lines. Double-kick drums deliver a thundering, galloping rhythm with relentless bass drum patterns and tight, punchy snare hits. Keyboard provides epic, orchestral-style pads with brass and string patches that add symphonic grandeur. The arrangement is triumphant and anthemic, with escalating intensity through each section and a virtuosic guitar solo. 168 BPM in F# Major, 4/4 time signature.', NULL, 'Power Metal', 168, 'F# Major', '4/4', 'Session 2, Verse-Chorus-Solo, 3 instruments');
